            type string;
        }

        leaf-list ACTIONS {
            type string;
            default "";
        }

        leaf-list BIND_POINTS {
            mandatory true;
            type enumeration {
                enum PORT;
                enum PORTCHANNEL;
            }
        }
    }
}
