  rpc Acknowledge(AcknowledgeRequest) returns (AcknowledgeResponse) {}

  // Artifact will stream the artifact contents for the provided artifact id.

rpc Acknowledge(AcknowledgeRequest) returns (AcknowledgeResponse) {}

  // Artifact will stream the artifact contents for the provided artifact id.
