class NotificationQueueBase {
public:
    virtual ~NotificationQueueBase() = default;
    virtual void               push(const std::string& msg) = 0;
    virtual const std::string& front() const                = 0;
    virtual void               pop()                        = 0;
    virtual bool               empty() const                = 0;
    virtual size_t             size()  const                = 0;
};
