  u32 samplingN;        /* configured 1-in-N rate for this port */
  u32 skip;             /* random-skip countdown */
  u32 pool;             /* sample_pool counter */

/* configured 1-in-N rate for this port */
  u32 skip;             /* random-skip countdown */
  u32 pool;             /* sample_pool counter */
